  const weedMin = Number.isFinite(parseFloat(weedingMinutesPerPartOverride))
    ? parseFloat(weedingMinutesPerPartOverride) : weedMinDefault;
  const installMin = Math.max(0, parseFloat(installMinutesPerPart) || 0);
