const stripMeta = (row) => {
  const payload = { ...row };
  ["id", "created_date", "updated_date", "created_by_id", "created_by", "is_sample"].forEach((key) => delete payload[key]);
  return payload;
};

const snapshot = (rows) => Object.fromEntries((rows || []).map((row) => [row.id, JSON.stringify(stripMeta(row))]));

export default function VinylSettings() {
  const [machines, setMachines] = useState([]);
  const [original, setOriginal] = useState({});
  const [loading, setLoading] = useState(true);
  const [savingId, setSavingId] = useState(null);
  const [user, setUser] = useState(null);
  const [message, setMessage] = useState("");
  const [error, setError] = useState("");
  const machineSaveRef = useRef(new Set());
  const addMachineRef = useRef(false);

  const isAdmin = user?.role === "admin";

  const load = async () => {
    setLoading(true);
    setError("");
    try {
      const [rows, me] = await Promise.all([
        loadAllEntityRows({ entity: VinylMachine, sort: "sort_order", label: "Vinyl machines" }),
        User.me().catch(() => null),
      ]);
      setMachines(rows || []);
      setOriginal(snapshot(rows || []));
      setUser(me);
    } catch (e) {
      setError(e.message || "Could not load Vinyl machines.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { load(); }, []);

  const dirtyIds = useMemo(() => new Set(
    machines.filter((row) => JSON.stringify(stripMeta(row)) !== original[row.id]).map((row) => row.id)
  ), [machines, original]);

  const patch = (id, changes) => setMachines((prev) => prev.map((row) => row.id === id ? { ...row, ...changes } : row));

  const save = async (machine) => {
    if (!isAdmin || !machine?.id || machineSaveRef.current.has(machine.id)) return;
    machineSaveRef.current.add(machine.id);
    setSavingId(machine.id);
    setError("");
    setMessage("");
    try {
      const live = await VinylMachine.get(machine.id);
      const loadedSnapshot = original[machine.id];
      const liveSnapshot = JSON.stringify(stripMeta(live || {}));
      const versionChanged = !!(machine.updated_date && live?.updated_date && machine.updated_date !== live.updated_date);
      if (!live || versionChanged || (loadedSnapshot !== undefined && liveSnapshot !== loadedSnapshot)) {
        if (live) {
          setMachines((prev) => prev.map((row) => row.id === machine.id ? live : row));
          setOriginal((prev) => ({ ...prev, [machine.id]: liveSnapshot }));
        }
        throw new Error("This Vinyl machine changed in another session. The latest machine data has been reloaded; review it before saving again.");
      }

      const payload = stripMeta(machine);
      const saved = await replaceEntityFieldsIfUnchanged({
        entity: VinylMachine,
        id: machine.id,
        expectedUpdatedAt: live.updated_date || "",
        expectedFields: expectedEntityFields(live, payload),
        nextFields: payload,
        guardFields: { machine_type: live.machine_type },
        label: `Vinyl machine ${live.machine_name || live.id}`,
      });
      setMachines((prev) => prev.map((row) => row.id === machine.id ? saved : row));
      setOriginal((prev) => ({ ...prev, [machine.id]: JSON.stringify(stripMeta(saved)) }));
      setMessage(`Saved ${saved.machine_name || machine.machine_name || "Vinyl machine"}.`);
    } catch (e) {
      if (!String(e?.message || "").includes("changed in another session")) {
        const refreshed = await VinylMachine.get(machine.id).catch(() => null);
        if (refreshed) {
          setMachines((prev) => prev.map((row) => row.id === machine.id ? refreshed : row));
          setOriginal((prev) => ({ ...prev, [machine.id]: JSON.stringify(stripMeta(refreshed)) }));
        }
      }
      setError(e.message || "Could not save Vinyl machine.");
    } finally {
      machineSaveRef.current.delete(machine.id);
      setSavingId(null);
    }
  };

  const addMachine = async (type) => {
    if (!isAdmin || addMachineRef.current) return;
    addMachineRef.current = true;
    setError("");
    setMessage("");
    try {
      const meta = TYPE_META[type] || TYPE_META.printer;
      const result = await createVinylMachineWithRecovery({
        entity: VinylMachine,
        data: {
          machine_name: `New ${meta.label}`,
          machine_type: type,
          is_active: false,
          is_default_for_type: false,
          sort_order: machines.length + 1,
        },
        label: `New ${meta.label}`,
      });
      const created = result.record;
      setMachines((prev) => [...prev.filter((row) => row.id !== created.id), created]);
      setOriginal((prev) => ({ ...prev, [created.id]: JSON.stringify(stripMeta(created)) }));
      setMessage(`Added ${meta.label}. It starts inactive so it cannot affect estimating until configured and enabled.`);
    } catch (e) {
      setError(e.message || "Could not add Vinyl machine.");
    } finally {
      addMachineRef.current = false;
