                  )}
                  <div className="flex justify-end mt-2 pt-2 border-t border-slate-200 text-sm">
                    <span className="text-slate-600 mr-2">Line Total:</span>
                    <span className="font-semibold tabular-nums">{fmt(row.total_cost)}</span>
                  </div>
                </div>
              ))}
              <div className="flex justify-end pt-2 border-t border-slate-200">
                <div className="text-right">
                  <div className="text-xs text-slate-500">Total Equipment Cost</div>
                  <div className="text-lg font-bold tabular-nums">{fmt(totalCost)}</div>
                </div>
              </div>
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

// Logic for suggesting equipment based on project line items.
// Pure functions — no React, no entity calls.

// Equipment types that lift workers to a height (used to match install height)
const LIFT_TYPES = ["ladder", "scissor_lift", "boom_lift", "boom_truck", "scaffold"];
const BOOM_TYPES = ["boom_lift", "boom_truck"];

// Vehicles needed to transport crew & gear to the site
const VEHICLE_TYPES = ["truck", "van", "flatbed", "boom_truck"];

// Owned equipment never carries a delivery / pickup fee (it's your own gear).
export function isOwnedEquipment(invOrRow = {}) {
  if (invOrRow.ownership) return invOrRow.ownership === "owned";
  return invOrRow.pricing_mode === "owned_flat" || invOrRow.pricing_mode === "per_project_flat";
}

// Is this inventory record owned (vs rented)?
const invIsOwned = (e) =>
  e.ownership === "owned" || e.pricing_mode === "owned_flat" || e.pricing_mode === "per_project_flat";

const safetyMarginOf = (e) => {
  const m = parseFloat(e.vertical_reach_safety_margin_feet);
  return isNaN(m) ? 2 : m;
};

// Does this lift reach the install height (with its safety margin)?
const liftReaches = (e, height) =>
  (parseFloat(e.max_height_feet) || 0) >= height + safetyMarginOf(e);

/**
 * Pick exactly ONE lift for the job. Selection order:
 *  1. A boom flagged `is_primary_owned` (your go-to owned boom) — used whenever
 *     it can reach the install height. This is the "normal use" default.
 *  2. A boom flagged `is_default_for_height` whose configured range contains
 *     the install height.
 *  3. Otherwise the SMALLEST lift that reaches the height — but OWNED lifts are
 *     always preferred over rented ones when both can reach. Only fall back to
 *     a rented lift when no owned lift is tall enough (install height exceeds
 *     your owned reach).
 * Never returns more than one lift.
 */
function pickLift(active, maxHeight) {
  const lifts = active.filter((e) => LIFT_TYPES.includes(e.equipment_type));
  if (lifts.length === 0) return null;

  // 1) Primary owned boom — your marked go-to, used whenever it reaches.
  const primaryOwned = lifts.find(
    (e) => invIsOwned(e) && e.is_primary_owned && liftReaches(e, maxHeight)
  );
  if (primaryOwned) return primaryOwned;

  // 2) Default-by-height-range boom.
  const defaultByRange = lifts.find((e) => {
    if (!BOOM_TYPES.includes(e.equipment_type)) return false;
    if (!e.is_default_for_height) return false;
    const min = parseFloat(e.default_height_min_feet) || 0;
    const max = parseFloat(e.default_height_max_feet) || 0;
    if (max <= 0) return false;
    return maxHeight >= min && maxHeight <= max;
  });
  if (defaultByRange) return defaultByRange;

  const bySize = (a, b) => (parseFloat(a.max_height_feet) || 0) - (parseFloat(b.max_height_feet) || 0);

  // 3a) Smallest OWNED lift that reaches (owned always preferred).
  const ownedReaching = lifts.filter((e) => invIsOwned(e) && liftReaches(e, maxHeight)).sort(bySize);
  if (ownedReaching.length > 0) return ownedReaching[0];

  // 3b) Install height exceeds owned reach → smallest RENTED lift that reaches.
  const rentedReaching = lifts.filter((e) => !invIsOwned(e) && liftReaches(e, maxHeight)).sort(bySize);
  if (rentedReaching.length > 0) return rentedReaching[0];

  // 3c) Nothing clears the safety margin — pick the tallest lift that at least
  //     physically reaches, preferring owned.
  const anyReaching = lifts
    .filter((e) => (parseFloat(e.max_height_feet) || 0) >= maxHeight)
    .sort((a, b) => {
      const own = (invIsOwned(b) ? 1 : 0) - (invIsOwned(a) ? 1 : 0);
      if (own !== 0) return own;
      return bySize(b, a); // tallest first
    });
  return anyReaching[0] || null;
}

/**
 * Given a list of line items and the equipment inventory, suggest which
 * pieces of equipment should be selected. Returns inventory items.
 * Always returns at most ONE lift + (if needed) ONE transport vehicle.
 */
export function suggestEquipmentForProject(items = [], inventory = []) {
  if (!items.length || !inventory.length) return [];

  const maxHeight = items.reduce(
    (m, it) => Math.max(m, parseFloat(it.installation_height_feet) || 0),
    0
  );

  const active = inventory.filter((e) => e.is_active !== false);
  const suggestions = [];

  // Exactly one lift for the job.
  const lift = pickLift(active, maxHeight);
  if (lift) suggestions.push(lift);

  // Add a transport vehicle (prefer owned) — unless the lift IS a vehicle (boom truck).
  const haveVehicle = suggestions.some((s) => VEHICLE_TYPES.includes(s.equipment_type));
  if (!haveVehicle) {
    const vehicles = active
      .filter((e) => VEHICLE_TYPES.includes(e.equipment_type))
      .sort((a, b) => (invIsOwned(a) ? 0 : 1) - (invIsOwned(b) ? 0 : 1));
    if (vehicles.length > 0) suggestions.push(vehicles[0]);
  }

  return suggestions;
}

/**
 * Build a `selected_equipment` row from an inventory equipment record.
 * Default duration = ON-SITE clock time (labor hours ÷ crew size) mapped to the
 * pricing mode — a 3-person crew burns 24 labor-hours in 8 site hours, so the
 * lift is only rented for 1 day, not 3.
 * For booms, seeds `idle_running_cost_per_hour` and `idle_hours` (defaults to labor hours).
 */
export function selectedEquipmentFromInventory(inv, projectLaborHours = 0, crewSize = 1) {
  const laborHours = parseFloat(projectLaborHours) || 0;
  // Equipment is rented for ON-SITE (clock) time, not man-hours.
  const crew = Math.max(1, parseInt(crewSize) || 1);
  const clockHours = laborHours / crew;
  const clockDays = Math.max(1, Math.ceil(clockHours / 8));

  let duration = 1;
  let unitCost = 0;

  switch (inv.pricing_mode) {
    case "per_hour":
      duration = Math.max(1, Math.ceil(clockHours));
      unitCost = parseFloat(inv.cost_per_hour) || 0;
      break;
    case "per_day":
      duration = clockDays;
      unitCost = parseFloat(inv.cost_per_day) || 0;
      break;
    case "per_week":
      duration = Math.max(1, Math.ceil(clockDays / 5));
      unitCost = parseFloat(inv.cost_per_week) || 0;
      break;
    case "per_month":
      duration = 1;
      unitCost = parseFloat(inv.cost_per_month) || 0;
      break;
    case "owned_flat":
    case "per_project_flat":
      duration = 1;
      unitCost = parseFloat(inv.cost_flat) || 0;
      break;
    default:
      duration = 1;
      unitCost = 0;
  }

  // Idle-running fields apply to booms only
  const isBoom = BOOM_TYPES.includes(inv.equipment_type);
  const idleRate = isBoom ? (parseFloat(inv.idle_running_cost_per_hour) || 0) : 0;
  // Default idle to on-site clock hours rounded up — most installs run the boom continuously
  const idleHours = isBoom && idleRate > 0 ? Math.max(0, Math.ceil(clockHours)) : 0;

  // Owned equipment never has a delivery / pickup fee.
  const owned = isOwnedEquipment(inv);

  return {
    equipment_id: inv.id,
    inventory_entity: inv._inventory_entity || inv.inventory_entity || "",
    equipment_name: inv.equipment_name,
    equipment_type: inv.equipment_type,
    pricing_mode: inv.pricing_mode,
    ownership: owned ? "owned" : (inv.ownership || "rented"),
    duration,
    include_delivery: false,
    delivery_pickup_cost: owned ? 0 : (parseFloat(inv.delivery_pickup_cost) || 0),
    unit_cost: unitCost,
    idle_running_cost_per_hour: idleRate,
    idle_hours: idleHours,
    idle_cost: idleRate * idleHours,
    total_cost: unitCost * duration + (idleRate * idleHours),
    notes: "",
  };
}

/**
 * Recalculate the total cost of a selected equipment row.
 */
export function recalcEquipmentRow(row) {
  const duration = parseFloat(row.duration) || 0;
  const unitCost = parseFloat(row.unit_cost) || 0;
  // Owned equipment never bills a delivery / pickup fee.
  const delivery = (!isOwnedEquipment(row) && row.include_delivery)
    ? parseFloat(row.delivery_pickup_cost) || 0
    : 0;
  const idleHours = parseFloat(row.idle_hours) || 0;
  const idleRate = parseFloat(row.idle_running_cost_per_hour) || 0;
  const idle_cost = idleHours * idleRate;
  return {
    ...row,
    idle_cost,
    total_cost: unitCost * duration + delivery + idle_cost,
  };
}

/**
 * Recalculate a personnel row's total cost.
 */
export function recalcPersonnelRow(row) {
  const rate = parseFloat(row.hourly_rate) || 0;
  const hours = parseFloat(row.hours) || 0;
  return { ...row, total_cost: rate * hours };
}

/**
 * Display label for a pricing mode's duration unit.
 */
export function durationUnitLabel(pricing_mode) {
  switch (pricing_mode) {
    case "per_hour": return "hours";
    case "per_day": return "days";
    case "per_week": return "weeks";
    case "per_month": return "months";
    case "owned_flat":
    case "per_project_flat":
      return "flat";
    default: return "units";
  }
}

/**
 * Suggested crew size for a project:
 *   - 3 people when max install height >= 40 ft OR 30+ total letters
 *   - otherwise 2 (Crew Lead + Installer)
 * Shared by the personnel suggester AND the equipment duration math so
 * on-site time assumptions stay consistent.
 */
export function suggestCrewSize(items = []) {
  const maxHeight = items.reduce(
    (m, it) => Math.max(m, parseFloat(it.installation_height_feet) || 0),
    0
  );
  const totalLetters = items.reduce(
    (s, it) => s + (parseFloat(it.qty_letters) || 0),
    0
  );
  return (maxHeight >= 40 || totalLetters >= 30) ? 3 : 2;
}

/**
 * Suggest an appropriate crew (Crew Lead / Installer / Helper) for a project.
 * Crew size comes from suggestCrewSize(); total crew hours = project labor
 * hours, divided evenly per person.
 */
export function suggestPersonnelForProject(items = [], projectLaborHours = 0, rateForRole = () => 0) {
  const crewSize = suggestCrewSize(items);

  const perPersonHours = projectLaborHours && crewSize > 0
    ? +(projectLaborHours / crewSize).toFixed(2)
    : 0;

  const roles = ["Crew Lead", "Installer", "Helper"];
  return Array.from({ length: crewSize }, (_, i) => {
    const role = roles[i] || "Installer";
    return recalcPersonnelRow({
      name: "",
      role,
      hourly_rate: rateForRole(role),
      hours: perPersonHours,
      total_cost: 0,
    });
  });
}

import React from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Plus, Trash2, Users, Wand2 } from "lucide-react";
import { recalcPersonnelRow, suggestPersonnelForProject } from "./equipmentSuggester";

const fmt = (v) => `$${(parseFloat(v) || 0).toFixed(2)}`;

const ROLE_OPTIONS = ["Crew Lead", "Installer", "Helper"];

const emptyRow = () => ({
  name: "",
  role: "Installer",
  hourly_rate: 0,
  hours: 0,
  total_cost: 0,
});

export default function PersonnelSelector({
  personnel = [],
  onChange,
  projectLaborHours = 0,
  roleRates = {},
  items = [],
}) {
  // Resolve the rate for a given role (fallback to Installer rate, then 0)
  const rateForRole = (role) => {
    const r = parseFloat(roleRates[role]);
    if (!isNaN(r) && r > 0) return r;
    const fallback = parseFloat(roleRates.Installer);
    return !isNaN(fallback) ? fallback : 0;
  };

  const handleAdd = () => {
    const row = emptyRow();
    row.hourly_rate = rateForRole(row.role);
    onChange([...personnel, row]);
  };

  const handleUpdate = (idx, patch) => {
    const next = [...personnel];
    const merged = { ...next[idx], ...patch };
    // When the role changes, auto-fill the rate from the role's setting
    if ("role" in patch && patch.role !== next[idx].role) {
      merged.hourly_rate = rateForRole(patch.role);
    }
    next[idx] = recalcPersonnelRow(merged);
    onChange(next);
  };

  const handleRemove = (idx) => {
    if (!confirm(`Remove "${personnel[idx]?.name || "this person"}"?`)) return;
    const next = [...personnel];
    next.splice(idx, 1);
    onChange(next);
  };

  // Quick-fill: build a suggested crew from project height & letter count.
  // Uses the shared suggestPersonnelForProject helper so the auto-trigger and
  // the manual button produce the exact same crew.
  const handleAutoFillCrew = () => {
    const newCrew = suggestPersonnelForProject(items, projectLaborHours, rateForRole);
    onChange(newCrew);
  };

  const totalCost = personnel.reduce(
    (s, p) => s + (parseFloat(p.total_cost) || 0),
    0
  );
  const totalHours = personnel.reduce(
    (s, p) => s + (parseFloat(p.hours) || 0),
    0
  );

  return (
    <Card className="bg-white border-0 shadow-sm">
      <CardHeader className="pb-3 flex flex-row items-center justify-between flex-wrap gap-2">
        <div>
          <CardTitle className="text-lg flex items-center gap-2">
            <Users className="w-5 h-5 text-purple-600" />
            Personnel ({personnel.length})
          </CardTitle>
          <p className="text-xs text-slate-500 mt-1">
            Assign crew members and their hours for this job.
          </p>
        </div>
        <div className="flex gap-2">
          <Button
            size="sm"
            variant="outline"
            onClick={handleAutoFillCrew}
            className="h-9 text-xs"
            title="Auto-suggest crew based on project size & height"
          >
            <Wand2 className="w-3.5 h-3.5 mr-1" /> Auto-Suggest Crew
          </Button>
          <Button
            size="sm"
            onClick={handleAdd}
            className="bg-purple-600 hover:bg-purple-700 text-white"
          >
            <Plus className="w-4 h-4 mr-1" /> Add Person
          </Button>
        </div>
      </CardHeader>
      <CardContent>
        {personnel.length === 0 ? (
          <div className="border-2 border-dashed border-slate-300 bg-slate-50/50 rounded-lg p-8 text-center">
            <Users className="w-8 h-8 text-slate-400 mx-auto mb-2" />
            <p className="text-sm text-slate-600 font-medium">No personnel assigned</p>
            <p className="text-xs text-slate-500 mt-1">
              Add crew members or use Auto-Suggest to populate based on the project.
            </p>
          </div>
        ) : (
          <div className="space-y-2">
            {personnel.map((row, idx) => (
              <div
                key={idx}
                className="border border-slate-200 rounded-lg p-3 bg-slate-50/50"
              >
                <div className="grid md:grid-cols-12 gap-2 items-end">
                  <div className="md:col-span-3">
                    <Label className="text-xs">Name</Label>
                    <Input
                      value={row.name}
                      onChange={(e) => handleUpdate(idx, { name: e.target.value })}
                      placeholder="e.g. Mike"
                      className="h-8 mt-0.5"
                    />
                  </div>
                  <div className="md:col-span-3">
                    <Label className="text-xs">Role</Label>
                    <select
                      value={row.role || "Installer"}
                      onChange={(e) => handleUpdate(idx, { role: e.target.value })}
                      className="h-8 mt-0.5 w-full border border-slate-200 rounded-md px-2 text-sm bg-white"
                    >
                      {ROLE_OPTIONS.map((r) => (
                        <option key={r} value={r}>{r}</option>
                      ))}
                    </select>
                  </div>
                  <div className="md:col-span-2">
                    <Label className="text-xs">Rate $/hr</Label>
                    <Input
                      type="number"
                      step="0.01"
                      value={row.hourly_rate}
                      onFocus={(e) => e.target.select()}
                      onChange={(e) =>
                        handleUpdate(idx, { hourly_rate: parseFloat(e.target.value) || 0 })
                      }
                      className="h-8 mt-0.5"
                    />
                  </div>
                  <div className="md:col-span-2">
                    <Label className="text-xs">Hours</Label>
                    <Input
                      type="number"
                      step="0.25"
                      value={row.hours}
                      onFocus={(e) => e.target.select()}
                      onChange={(e) =>
                        handleUpdate(idx, { hours: parseFloat(e.target.value) || 0 })
                      }
                      className="h-8 mt-0.5"
                    />
                  </div>
                  <div className="md:col-span-1">
                    <Label className="text-xs">Total</Label>
                    <div className="h-8 mt-0.5 text-sm font-medium flex items-center tabular-nums">
                      {fmt(row.total_cost)}
                    </div>
                  </div>
                  <div className="md:col-span-1 flex items-end justify-end">
                    <Button
                      size="sm"
                      variant="ghost"
                      onClick={() => handleRemove(idx)}
                      className="text-red-500 hover:bg-red-50 h-8 w-8 p-0"
                    >
                      <Trash2 className="w-3.5 h-3.5" />
                    </Button>
                  </div>
                </div>
              </div>
            ))}
            <div className="flex justify-between pt-2 border-t border-slate-200 text-sm">
              <div>
                <span className="text-slate-500">Total Hours:</span>{" "}
                <span className="font-semibold tabular-nums">{totalHours.toFixed(2)}</span>
                {projectLaborHours > 0 && (
                  <span className="text-xs text-slate-400 ml-2">
                    (calculated: {projectLaborHours.toFixed(2)} hrs)
                  </span>
                )}
              </div>
              <div className="text-right">
                <span className="text-xs text-slate-500">Total Personnel Cost: </span>
                <span className="text-lg font-bold tabular-nums">{fmt(totalCost)}</span>
              </div>
            </div>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

import React, { useState, useMemo, useEffect } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { MapPin, Fuel, RefreshCw, AlertCircle } from "lucide-react";
import { base44 } from "@/api/base44Client";
import { getSessionToken } from "@/components/auth/EmailGate";

const fmt = (v) => `$${(parseFloat(v) || 0).toFixed(2)}`;

/**
 * Travel cost line on the Crew tab.
 * - Shop address comes from Settings (install_shop_address)
 * - Site address comes from the project
 * - User clicks "Calculate Miles" → backend LLM returns round-trip miles
 * - For each OWNED vehicle in selected_equipment, computes: miles / mpg × fuel_price
 * - Adds travel labor (round-trip time × travel_labor_rate × personnel count) and per-mile overhead
 */
export default function TravelCostCard({
  shopAddress,
  siteAddress,
  selectedEquipment = [],
  equipmentInventory = [],
  personnel = [],
  settings = {},
  travelMiles = 0,
  onMilesChange,
  onTotalChange,
  autoTriggerKey, // changing this value causes a re-calc (used when the Crew tab is entered)
}) {
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  // Tracks the last shop/site pair we auto-calculated for, to avoid loops.
  const [lastAutoKey, setLastAutoKey] = useState(null);

  const gasPrice = parseFloat(settings.install_gasoline_price_per_gallon) || 3.5;
  const dieselPrice = parseFloat(settings.install_diesel_price_per_gallon) || 4.0;
  const travelLaborRate = parseFloat(settings.install_travel_labor_rate) || 45;
  const avgSpeed = parseFloat(settings.install_travel_avg_speed_mph) || 45;
  const overheadPerMile = parseFloat(settings.install_travel_overhead_per_mile) || 0;
  const minCharge = parseFloat(settings.install_min_travel_charge) || 0;

  // Resolve OWNED vehicles from selected_equipment by looking up the inventory record
  const ownedVehicles = useMemo(() => {
    const VEHICLE_TYPES = new Set(["truck", "van", "flatbed", "car", "boom_truck"]);
    return selectedEquipment
      .map(se => {
        const inv = equipmentInventory.find(i => i.id === se.equipment_id);
        if (!inv) return null;
        if (inv.ownership !== "owned") return null;
        if (!VEHICLE_TYPES.has(inv.equipment_type)) return null;
        const mpg = parseFloat(inv.mpg);
        if (!mpg || mpg <= 0) return null;
        return {
          equipment_id: inv.id,
          name: inv.equipment_name,
          mpg,
          fuel_type: inv.fuel_type === "diesel" ? "diesel" : "gasoline",
        };
      })
      .filter(Boolean);
  }, [selectedEquipment, equipmentInventory]);

  const miles = parseFloat(travelMiles) || 0;
  const personnelCount = Math.max(1, (personnel || []).length);

  // Per-vehicle fuel cost (each vehicle drives the full distance)
  const vehicleLines = ownedVehicles.map(v => {
    const gallons = miles / v.mpg;
    const pricePerGal = v.fuel_type === "diesel" ? dieselPrice : gasPrice;
    const fuelCost = gallons * pricePerGal;
    return { ...v, gallons, pricePerGal, fuelCost };
  });

  const totalFuelCost = vehicleLines.reduce((s, v) => s + v.fuelCost, 0);
  // Travel time: round-trip miles ÷ avg speed = hours per person; × crew size
  const travelHoursPerPerson = avgSpeed > 0 ? miles / avgSpeed : 0;
  const totalTravelLaborCost = travelHoursPerPerson * personnelCount * travelLaborRate;
  const overheadCost = miles * overheadPerMile;

  const subtotal = totalFuelCost + totalTravelLaborCost + overheadCost;
  const totalTravelCost = miles > 0 ? Math.max(subtotal, minCharge) : 0;

  // Push the computed total back up to the project so it's included in the rollup.
  useEffect(() => {
    if (typeof onTotalChange === "function") {
      onTotalChange(totalTravelCost);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [totalTravelCost]);

  const handleCalculate = async () => {
    if (!shopAddress?.trim() || !siteAddress?.trim()) {
      setError("Shop address (in Settings) and Site Address (on Project tab) are both required.");
      return;
    }
    setError(null);
    setLoading(true);
    try {
      const res = await base44.functions.invoke("calculateTravelMiles", { shop_address: shopAddress, site_address: siteAddress, session_token: getSessionToken() });
      const rt = parseFloat(res?.data?.round_trip_miles);
      if (!isFinite(rt) || rt <= 0) {
        setError(res?.data?.error || "Could not estimate distance for those addresses.");
      } else {
        onMilesChange?.(rt);
      }
    } catch (e) {
      setError(e.message || "Travel calculation failed.");
    }
    setLoading(false);
  };

  // Auto-calculate when the Crew tab is entered (autoTriggerKey changes),
  // as long as we have addresses and haven't already calculated this exact pair.
  useEffect(() => {
    if (autoTriggerKey == null) return;
    const key = `${shopAddress || ""}|${siteAddress || ""}`;
    if (!shopAddress?.trim() || !siteAddress?.trim()) return;
    if (lastAutoKey === key) return;
    // Skip if we already have miles for this pair (e.g. loaded from saved project)
    if ((parseFloat(travelMiles) || 0) > 0 && lastAutoKey === null) {
      setLastAutoKey(key);
      return;
    }
    setLastAutoKey(key);
    handleCalculate();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [autoTriggerKey, shopAddress, siteAddress]);

  return (
    <Card className="bg-white border-0 shadow-sm">
      <CardHeader className="pb-3">
        <CardTitle className="text-lg flex items-center gap-2">
          <MapPin className="w-5 h-5 text-purple-600" />
          Travel & Fuel
        </CardTitle>
        <p className="text-xs text-slate-500 mt-1">
          Round-trip travel from shop → site. Fuel is summed per OWNED vehicle (each drives the full distance).
        </p>
      </CardHeader>
      <CardContent className="space-y-3">
        {/* Address summary + miles control */}
        <div className="grid md:grid-cols-3 gap-3 text-xs">
          <div>
            <div className="text-slate-500 mb-0.5">Shop (from Settings)</div>
            <div className="font-medium text-slate-800 truncate" title={shopAddress}>
              {shopAddress || <span className="text-red-500">Not set</span>}
            </div>
          </div>
          <div>
            <div className="text-slate-500 mb-0.5">Site Address</div>
            <div className="font-medium text-slate-800 truncate" title={siteAddress}>
              {siteAddress || <span className="text-amber-600">Not set on Project tab</span>}
            </div>
          </div>
          <div>
            <Label className="text-xs text-slate-500">Round-Trip Miles</Label>
            <div className="flex gap-2 mt-0.5">
              <Input
                type="number"
                step="0.1"
                value={miles}
                onFocus={(e) => e.target.select()}
                onChange={(e) => onMilesChange?.(parseFloat(e.target.value) || 0)}
                className="h-8 text-sm tabular-nums"
              />
              <Button
                size="sm"
                variant="outline"
                onClick={handleCalculate}
                disabled={loading || !shopAddress || !siteAddress}
                className="h-8 text-xs whitespace-nowrap"
                title="Auto-estimate using AI/web"
              >
                {loading ? (
                  <RefreshCw className="w-3 h-3 animate-spin" />
                ) : (
                  <><RefreshCw className="w-3 h-3 mr-1" /> Auto</>
                )}
              </Button>
            </div>
          </div>
        </div>

        {error && (
          <div className="flex items-start gap-2 p-2 bg-red-50 border border-red-200 rounded-md text-xs text-red-700">
            <AlertCircle className="w-3.5 h-3.5 flex-shrink-0 mt-0.5" />
            <span>{error}</span>
          </div>
        )}

        {/* Vehicle breakdown */}
        {miles > 0 && (
          <div className="border border-slate-200 rounded-lg overflow-hidden">
            {vehicleLines.length === 0 ? (
              <div className="p-3 text-xs text-slate-500 bg-slate-50">
                No OWNED vehicles selected with an MPG value. Add a truck/van in Equipment Inventory (ownership = owned, mpg &gt; 0) and select it on this estimate.
              </div>
            ) : (
              <table className="w-full text-xs">
                <thead className="bg-slate-50 text-slate-600">
                  <tr>
                    <th className="text-left px-3 py-1.5 font-medium">Vehicle</th>
                    <th className="text-right px-3 py-1.5 font-medium">MPG</th>
                    <th className="text-right px-3 py-1.5 font-medium">Gallons</th>
                    <th className="text-right px-3 py-1.5 font-medium">$/gal</th>
                    <th className="text-right px-3 py-1.5 font-medium">Fuel Cost</th>
                  </tr>
                </thead>
                <tbody>
                  {vehicleLines.map((v, i) => (
                    <tr key={i} className="border-t border-slate-100">
                      <td className="px-3 py-1.5 flex items-center gap-1">
                        <Fuel className={`w-3 h-3 ${v.fuel_type === "diesel" ? "text-amber-600" : "text-emerald-600"}`} />
                        <span>{v.name}</span>
                        <span className="text-[10px] text-slate-400 uppercase">({v.fuel_type})</span>
                      </td>
                      <td className="px-3 py-1.5 text-right tabular-nums">{v.mpg.toFixed(1)}</td>
                      <td className="px-3 py-1.5 text-right tabular-nums">{v.gallons.toFixed(2)}</td>
                      <td className="px-3 py-1.5 text-right tabular-nums">${v.pricePerGal.toFixed(3)}</td>
                      <td className="px-3 py-1.5 text-right tabular-nums font-medium">{fmt(v.fuelCost)}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
          </div>
        )}

        {/* Rollup */}
        {miles > 0 && (
          <div className="space-y-1 pt-1 border-t border-slate-200 text-sm">
            <div className="flex justify-between text-xs text-slate-600">
              <span>Fuel ({vehicleLines.length} vehicle{vehicleLines.length === 1 ? "" : "s"})</span>
              <span className="tabular-nums">{fmt(totalFuelCost)}</span>
            </div>
            <div className="flex justify-between text-xs text-slate-600">
              <span>Travel Labor ({travelHoursPerPerson.toFixed(2)} hr × {personnelCount} ppl × ${travelLaborRate}/hr)</span>
              <span className="tabular-nums">{fmt(totalTravelLaborCost)}</span>
            </div>
            {overheadPerMile > 0 && (
              <div className="flex justify-between text-xs text-slate-600">
                <span>Vehicle Overhead ({miles.toFixed(1)} mi × ${overheadPerMile}/mi)</span>
                <span className="tabular-nums">{fmt(overheadCost)}</span>
              </div>
            )}
            {minCharge > 0 && subtotal < minCharge && (
              <div className="flex justify-between text-xs text-amber-700">
                <span>Minimum Travel Charge floor applied</span>
                <span className="tabular-nums">{fmt(minCharge)}</span>
              </div>
            )}
            <div className="flex justify-between pt-1 border-t border-slate-200">
              <span className="text-sm font-semibold text-slate-900">Total Travel Cost</span>
              <span className="text-lg font-bold tabular-nums">{fmt(totalTravelCost)}</span>
            </div>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

import { channelSellEconomics } from "./channel/channelSellPricing";

import { vinylEngineEconomics } from "./vinyl/vinylEnginePricing";

import { brickEngineEconomics } from "./brick/brickSellPricing";

import { cncEngineEconomics } from "./cnc/cncSellPricing";

import { metalEngineEconomics } from "./metal/metalSellPricing";

import { laserEngineEconomics } from "./laser/laserSellPricing";

import { paintEngineEconomics } from "./paint/paintSellPricing";

import { foundationEngineEconomics } from "./foundation/foundationSellPricing";

import { customItemsEngineEconomics } from "./customItems/customItemsSellPricing";

import { maintenanceEngineEconomics } from "./maintenance/maintenanceSellPricing";

const num = (value, fallback = 0) => Number.isFinite(Number(value)) ? Number(value) : fallback;

export function hasNumericValue(value) {
  return value !== undefined && value !== null && value !== "" && Number.isFinite(Number(value));
}

export function acceptedCustomerUnitPrice(line) {
  return hasNumericValue(line?.customer_price_snapshot)
    ? Number(line.customer_price_snapshot)
    : num(line?.total_snapshot);
}

export function liveCustomerUnitPrice(line) {
  if (hasNumericValue(line?.live_customer_price_snapshot)) return Number(line.live_customer_price_snapshot);
  if (hasNumericValue(line?.customer_price_snapshot)) return Number(line.customer_price_snapshot);
  return num(line?.live_total_snapshot, num(line?.total_snapshot));
}

export function acceptedInternalEstimateCost(lineItems = []) {
  return (lineItems || []).reduce((sum, line) => {
    const quantity = Math.max(0, num(line?.customer_quantity, 1));
    return sum + num(line?.total_snapshot) * quantity;
  }, 0);
}

export function manualCustomerPriceState({ detached = false, recalcRequired = false } = {}) {
  if (detached) return "detached_parts";
  if (recalcRequired) return "changed";
  return "manual";
}

// A Builder's source record may contain both shop/internal cost and an existing
// customer-facing sell-price calculation. Keep those concepts separate without
// changing the Builder's own established formulas.
export function sourceProjectEconomics(moduleKey, record, fallbackTotal = 0, pricingContext = null) {
  const fallback = num(fallbackTotal);
  if (!record) return { internalCost: fallback, customerPrice: fallback };

  const total = num(record.total_cost, fallback);
  const savedTierCustomerPrice = record?.customer_pricing?.applied === true && hasNumericValue(record?.customer_pricing?.total)
    ? num(record.customer_pricing.total)
    : null;
  const withSavedTier = (economics) => savedTierCustomerPrice === null
    ? economics
    : { ...economics, customerPrice: savedTierCustomerPrice };

  if (moduleKey === "foundation") {
    const cost = fallback;
    const markupPercent = num(record.customer_markup_percent);
    const override = num(record.customer_price_override);
    const baselineSell = override > 0 ? override : cost * (1 + markupPercent / 100);
    // F-23h pricing-engine wire: when the saved foundation record explicitly
    // carries engine config (engine_pricing-style context block or component-
    // scoped descriptors on the persisted split-total cost components), the
    // shared engine owns the sell side and wins over a legacy saved
    // customer_pricing snapshot. The module cost math above stays
    // authoritative; with no config the wire returns null and the record
    // keeps today's numbers byte-identically — the manual markup/override
    // and the saved Markup-Tier snapshot still apply.
    const wired = foundationEngineEconomics(record, { baselineSell, internalCost: cost, markupPercent, pricingContext });
    if (wired) {
      return {
        internalCost: wired.internalCost,
        customerPrice: wired.customerPrice,
        pricing_engine: wired.resolution,
      };
    }
    return withSavedTier({ internalCost: cost, customerPrice: baselineSell });
  }

  if (["vinyl", "brick_stone", "maintenance"].includes(moduleKey)) {
    const internalCost = hasNumericValue(record.subtotal)
      ? num(record.subtotal)
      : total - num(record.markup_amount);
    // F-23b/F-23c/F-23i pricing-engine wires: when the saved vinyl/brick/
    // maintenance record explicitly carries engine config (pricing_engine/
    // engine_pricing context block or per-line/component tier/template
    // descriptors), the shared engine owns the sell side and wins over a
    // legacy saved customer_pricing snapshot. The module cost math above
    // stays authoritative; with no config this returns null and the record
    // keeps today's numbers byte-identically.
    const wired = moduleKey === "vinyl"
      ? vinylEngineEconomics(record, { baselineSell: total, internalCost, pricingContext })
      : moduleKey === "brick_stone"
        ? brickEngineEconomics(record, { baselineSell: total, internalCost, pricingContext })
        : moduleKey === "maintenance"
          ? maintenanceEngineEconomics(record, { baselineSell: total, internalCost, pricingContext })
          : null;
    if (wired) {
      return {
        internalCost: wired.internalCost,
        customerPrice: wired.customerPrice,
        pricing_engine: wired.resolution,
      };
    }
    return withSavedTier({ internalCost, customerPrice: total });
  }

  if (moduleKey === "channel_letters") {
    const letterMarkup = num(record.total_letters_cost) - num(record.letters_subtotal);
    const projectSubtotal = hasNumericValue(record.subtotal)
      ? num(record.subtotal)
      : total - num(record.markup_amount);
    const internalCost = projectSubtotal - letterMarkup;
    // F-23a pricing-engine wire: when the saved record explicitly carries
    // engine config (pricing_engine context block or per-line tier/template
    // descriptors), the shared engine owns the sell side and wins over a
    // legacy saved customer_pricing snapshot. The module cost math above
    // stays authoritative; with no config this returns null and the record
    // keeps today's numbers byte-identically.
    const wired = channelSellEconomics(record, { internalCost, customerPrice: total });
    if (wired) {
      return {
        internalCost: wired.internalCost,
        customerPrice: wired.customerPrice,
        pricing_engine: wired,
      };
    }
    return withSavedTier({ internalCost, customerPrice: total });
  }

  if (moduleKey === "cnc") {
    // F-23d pricing-engine wire: when the saved CNC record explicitly carries
    // engine config (engine_pricing-style context block or per-line
    // tier/template descriptors on items[]), the shared engine owns the sell
    // side and wins over a legacy saved customer_pricing snapshot. CNC
    // total_cost is a pure cost total (no module markup), so the internal
    // cost and the sell baseline are the same number. With no config the
    // wire returns null and the record keeps today's numbers
    // byte-identically — the saved Markup-Tier snapshot still applies.
    const wired = cncEngineEconomics(record, { baselineSell: total, internalCost: total, pricingContext });
    if (wired) {
      return {
        internalCost: wired.internalCost,
        customerPrice: wired.customerPrice,
        pricing_engine: wired.resolution,
      };
    }
    return withSavedTier({ internalCost: total, customerPrice: total });
  }

  if (moduleKey === "laser") {
    // F-23e pricing-engine wire: when the saved laser record explicitly
    // carries engine config (engine_pricing-style context block or per-line
    // tier/template descriptors on items[]), the shared engine owns the sell
    // side and wins over a legacy saved customer_pricing snapshot. Laser
    // total_cost is a pure cost total (no module markup), so the internal
    // cost and the sell baseline are the same number. With no config the
    // wire returns null and the record keeps today's numbers
    // byte-identically — the saved Markup-Tier snapshot still applies.
    const wired = laserEngineEconomics(record, { baselineSell: total, internalCost: total, pricingContext });
    if (wired) {
      return {
        internalCost: wired.internalCost,
        customerPrice: wired.customerPrice,
        pricing_engine: wired.resolution,
      };
    }
    return withSavedTier({ internalCost: total, customerPrice: total });
  }

  if (moduleKey === "metal") {
    const internalCost = hasNumericValue(record.subtotal)
      ? num(record.subtotal)
      : total - num(record.markup_amount);
    // F-23f pricing-engine wire: when the saved metal record explicitly
    // carries engine config (engine_pricing-style context block or per-line
    // tier/template descriptors on items[]), the shared engine owns the sell
    // side and wins over a legacy saved customer_pricing snapshot. The
    // module cost math above stays authoritative; with no config the wire
    // returns null and the record keeps today's numbers byte-identically —
    // the saved Markup-Tier snapshot still applies.
    const wired = metalEngineEconomics(record, { baselineSell: total, internalCost, pricingContext });
    if (wired) {
      return {
        internalCost: wired.internalCost,
        customerPrice: wired.customerPrice,
        pricing_engine: wired.resolution,
      };
    }
    return withSavedTier({ internalCost, customerPrice: total });
  }

  if (moduleKey === "painting") {
    // F-23g pricing-engine wire: when the saved paint record explicitly
    // carries engine config (engine_pricing-style context block or per-line
    // tier/template descriptors on items[]), the shared engine owns the sell
    // side and wins over a legacy saved customer_pricing snapshot. Paint
    // records have no total_cost field and no module markup — the baseline
    // sell is the pure cost sum (total_paint_mask_cost +
    // total_liquid_paint_and_supplies_cost + total_labor_cost via
    // sourceProjectTotal's painting branch, which `total` resolves to since
    // record.total_cost is absent) — so the internal cost and the sell
    // baseline are the same number. With no config the wire returns null
    // and the record keeps today's numbers byte-identically — the saved
    // Markup-Tier snapshot still applies.
    const wired = paintEngineEconomics(record, { baselineSell: total, internalCost: total, pricingContext });
    if (wired) {
      return {
        internalCost: wired.internalCost,
        customerPrice: wired.customerPrice,
        pricing_engine: wired.resolution,
      };
    }
    return withSavedTier({ internalCost: total, customerPrice: total });
  }

  if (moduleKey === "custom_items") {
    // F-23j pricing-engine wire: when the saved custom-items record explicitly
    // carries engine config (engine_pricing-style context block or per-line
    // tier/template descriptors on items[]), the shared engine owns the sell
    // side and wins over a legacy saved customer_pricing snapshot.
    // CustomItemsProject.total_cost is a pure cost total (sum of the
    // extended item_total_cost fields — no module markup), so the internal
    // cost and the sell baseline are the same number. With no config the
    // wire returns null and the record keeps today's numbers
    // byte-identically — the fallback economics and the saved Markup-Tier
    // snapshot still apply.
    const wired = customItemsEngineEconomics(record, { baselineSell: total, internalCost: total, pricingContext });
    if (wired) {
      return {
        internalCost: wired.internalCost,
        customerPrice: wired.customerPrice,
        pricing_engine: wired.resolution,
      };
    }
    return withSavedTier({ internalCost: fallback, customerPrice: fallback });
  }

  return withSavedTier({ internalCost: fallback, customerPrice: fallback });
}

import React, { useEffect, useMemo, useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Label } from "@/components/ui/label";
import { TrendingUp, Info } from "lucide-react";
import { applyMarkups, parseVolumeDiscountBrackets, parseVolumeDiscountCategories } from "./markupEngine";
import { loadCustomerPricingConfig } from "./savedCustomerPricing";
import TierBadge, { getTierTheme } from "./TierBadge";

const fmt = (n) => "$" + (Number(n) || 0).toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 });

/**
 * Reusable Customer Pricing Summary tab for every estimator.
 *
 * Props:
 *   project      — the in-memory project object with totals
 *   categorize   — function(project) => [{ module, label, cost, category_key }]
 *   accentColor  — tailwind color name (purple, red, green, blue, orange) for the header
 *   onTierChange — optional callback. When provided, selected tier becomes the Builder's saved tier on next save.
 *   onApplyTier  — optional explicit-apply callback for Builders that already have a working manual pricing mode.
 */
export default function CustomerPricingTab({ project, categorize, accentColor = "slate", onTierChange, onApplyTier }) {
  const [tiers, setTiers] = useState([]);
  const [categories, setCategories] = useState([]);
  const [settings, setSettings] = useState([]);
  const [tierNumber, setTierNumber] = useState(1);
  const [customerDefaultTier, setCustomerDefaultTier] = useState(1);
  const [loading, setLoading] = useState(true);
  const [loadError, setLoadError] = useState("");

  useEffect(() => {
    let active = true;
    (async () => {
      if (active) {
        setLoading(true);
        setLoadError("");
      }
      try {
        const config = await loadCustomerPricingConfig(project);
        if (!active) return;
        setTiers(config.tiers || []);
        setCategories(config.categories || []);
        setSettings(config.settings || []);
        setCustomerDefaultTier(Number(config.customer?.pricing_tier) || 1);
        setTierNumber(Number(config.defaultTierNumber) || 1);
      } catch (e) {
        console.error("CustomerPricingTab load error:", e);
        if (active) setLoadError(e?.message || "Customer pricing configuration could not be verified.");
      }
      if (active) setLoading(false);
    })();
    return () => { active = false; };
  }, [project?.customer_id]);

  useEffect(() => {
    const savedTier = Number(project?.customer_pricing?.tier_number || project?.customer_pricing_tier);
    if (savedTier > 0 && tiers.some((tier) => Number(tier.tier_number) === savedTier)) {
      setTierNumber(savedTier);
    }
  }, [project?.customer_pricing?.tier_number, project?.customer_pricing_tier, tiers]);

  const selectedTier = useMemo(
    () => tiers.find((t) => t.tier_number === Number(tierNumber)) || tiers[0],
    [tiers, tierNumber]
  );

  const lines = useMemo(() => {
    try {
      return categorize(project) || [];
    } catch (e) {
      console.error("categorize error:", e);
      return [];
    }
  }, [project, categorize]);

  const markupResult = useMemo(() => {
    const brackets = parseVolumeDiscountBrackets(settings);
    const eligibleCategoryKeys = parseVolumeDiscountCategories(settings);
    const categoryFlags = Object.fromEntries(
      (categories || []).map((c) => [c?.category_key, c?.volume_discount_eligible]).filter(([k]) => k),
    );
    return applyMarkups(lines, selectedTier, { brackets, eligibleCategoryKeys, categoryFlags });
  }, [lines, selectedTier, settings, categories]);

  const categoryNameByKey = useMemo(
    () => Object.fromEntries(categories.map((c) => [c.category_key, c.category_name])),
    [categories]
  );

  // Group lines by category for display
  const byCategory = useMemo(() => {
    const map = {};
    markupResult.lines.forEach((l) => {
      const key = l.category_key;
      if (!map[key]) {
        map[key] = { name: categoryNameByKey[key] || key, lines: [], rawTotal: 0, finalTotal: 0 };
      }
      map[key].lines.push(l);
      map[key].rawTotal += l.cost;
      map[key].finalTotal += l.final_cost;
    });
    return map;
  }, [markupResult, categoryNameByKey]);

  const theme = getTierTheme(tierNumber);

  if (loading) {
    return (
      <Card className="bg-white border-0 shadow-sm">
        <CardContent className="p-8 text-center text-slate-500">Loading pricing tiers…</CardContent>
      </Card>
    );
  }

  if (loadError) {
    return (
      <Card className="bg-red-50 border-red-200">
        <CardContent className="p-6 text-sm text-red-900">
          <div className="flex items-start gap-2">
            <Info className="w-4 h-4 mt-0.5 flex-shrink-0" />
            <div>
              <p className="font-medium mb-1">Customer pricing unavailable</p>
              <p className="text-xs">{loadError}</p>
              <p className="text-xs mt-1">Tier-based customer pricing is not treated as missing or recalculated from fallback configuration while these pricing records cannot be verified.</p>
            </div>
          </div>
        </CardContent>
      </Card>
    );
  }

  if (tiers.length === 0) {
    return (
      <Card className="bg-amber-50 border-amber-200">
        <CardContent className="p-6 text-sm text-amber-900">
          <div className="flex items-start gap-2">
            <Info className="w-4 h-4 mt-0.5 flex-shrink-0" />
            <div>
              <p className="font-medium mb-1">No pricing tiers configured</p>
              <p className="text-xs">
                Visit <span className="font-semibold">Admin → Markups</span> to set up tier markups before using this view.
              </p>
            </div>
          </div>
        </CardContent>
      </Card>
    );
  }

