                 data-[state=inactive]:text-slate-500 data-[state=inactive]:hover:text-slate-700
                 gap-1.5 text-sm h-9 px-3 rounded-md"
    >
      <Icon className="w-3.5 h-3.5" />
      {label}
    </TabsTrigger>
  );
}

function Stat({ label, value, highlight }) {
  return (
    <div className="text-right">
      <div className="text-[10px] uppercase tracking-wider text-slate-300">{label}</div>
      <div className={`font-semibold tabular-nums ${highlight ? "text-emerald-300" : "text-white"}`}>{value}</div>
    </div>
  );
}

function Field({ label, required, children }) {
  return (
    <div className="space-y-1.5">
      <Label className="text-[11px] uppercase tracking-wider text-slate-600 font-medium">
        {label}{required && <span className="text-red-500 ml-0.5">*</span>}
      </Label>
      {children}
    </div>
  );
}

function SectionGrid({ cols = 4, children }) {
  const gridClass = cols === 2 ? "md:grid-cols-2"
                  : cols === 3 ? "md:grid-cols-3"
                  : "md:grid-cols-4";
  return <div className={`grid grid-cols-1 ${gridClass} gap-4`}>{children}</div>;
}

function NumberField({ label, value, disabled, onChange, step = "1" }) {
  return (
    <Field label={label}>
      <Input type="number" step={step}
        value={value ?? ""}
        disabled={disabled}
        onChange={(e) => onChange(e.target.value === "" ? 0 : parseFloat(e.target.value))}
        className="h-9 text-sm tabular-nums" />
    </Field>
  );
}

function SelectField({ label, value, disabled, onChange, options }) {
  return (
    <Field label={label}>
      <Select value={value || ""} onValueChange={onChange} disabled={disabled}>
        <SelectTrigger className="h-9 text-sm"><SelectValue placeholder="Select..." /></SelectTrigger>
        <SelectContent>
          {options.map(o => <SelectItem key={o.id} value={o.id}>{o.label}</SelectItem>)}
        </SelectContent>
      </Select>
    </Field>
  );
}

function ToggleField({ label, value, disabled, onChange }) {
  return (
    <div className="flex items-center justify-between gap-2 bg-white rounded-md border border-slate-200 px-3 h-9">
      <span className="text-xs text-slate-700 truncate">{label}</span>
      <Switch checked={!!value} onCheckedChange={onChange} disabled={disabled} />
    </div>
  );
}

function ChipGroup({ options, selected = [], onToggle, disabled, activeColor = "blue" }) {
  const onClass = activeColor === "purple"
    ? "bg-purple-600 border-purple-600 text-white"
    : "bg-blue-600 border-blue-600 text-white";
  const hoverClass = activeColor === "purple" ? "hover:border-purple-300" : "hover:border-blue-300";
  return (
    <div className="flex flex-wrap gap-1.5">
      {options.map(s => {
        const on = selected.includes(s);
        return (
          <button type="button"
            key={s}
            type="button"
            disabled={disabled}
            onClick={() => onToggle(s)}
            className={`text-[11px] px-3 py-1.5 rounded-full border transition-colors ${
              on ? onClass : `bg-white border-slate-200 text-slate-700 ${hoverClass}`
            } ${disabled ? "opacity-60 cursor-not-allowed" : ""}`}
          >
            {s.replace(/_/g, " ")}
          </button>
        );
      })}
    </div>
  );
}

import {
  deleteEntityIfUnchanged,
  expectedEntityFields,
  replaceEntityFieldsIfUnchanged,
} from "@/components/estimator/builder/builderEntityPersistence";

function normalized(value) {
  if (Array.isArray(value)) return value.map(normalized);
  if (!value || typeof value !== "object") return value;
  return Object.keys(value).sort().reduce((out, key) => {
    out[key] = normalized(value[key]);
    return out;
  }, {});
}

function sameValue(a, b) {
  return JSON.stringify(normalized(a)) === JSON.stringify(normalized(b));
}

function stripMeta(row = {}) {
  const payload = { ...row };
  ["id", "created_date", "updated_date", "created_by_id"].forEach((key) => delete payload[key]);
  return payload;
}

function rowMatchesData(row, data) {
  return Object.entries(data || {}).every(([key, value]) => sameValue(row?.[key], value));
}

export async function createVinylRecordWithRecovery({ entity, data, label = "Vinyl inventory record" } = {}) {
  const name = String(data?.vinyl_name || "").trim();
  if (!name || typeof entity?.filter !== "function" || typeof entity?.create !== "function") {
    throw new Error(`${label} could not initialize its retry-safe create.`);
  }

  const readMatches = async () => {
    const rows = await entity.filter({ vinyl_name: name });
    if (!Array.isArray(rows)) throw new Error(`${label} lookup did not return a record list.`);
    return rows.filter((row) => rowMatchesData(row, data));
  };

  const before = await readMatches();
  const beforeIds = new Set(before.map((row) => row.id));

  let created = null;
  let createError = null;
  try {
    created = await entity.create(data);
  } catch (error) {
    createError = error;
  }

  if (created?.id) {
    const saved = typeof entity.get === "function" ? await entity.get(created.id).catch(() => null) : null;
    return { record: saved?.id ? saved : created, status: "created", ownershipCertain: true };
  }

  const after = await readMatches();
  const newMatches = after.filter((row) => !beforeIds.has(row.id));
  if (newMatches.length === 1) {
    return { record: newMatches[0], status: "recovered", ownershipCertain: false };
  }
  if (newMatches.length > 1) {
    throw new Error(`${label} may have been created more than once while the create response was unavailable. No rows were deleted; reload and review the new matching records before retrying.`);
  }

  if (createError) throw createError;
  throw new Error(`${label} could not verify whether it was created. Reload before retrying.`);
}

export async function updateVinylIfUnchanged({ entity, record, nextFields, label = "Vinyl inventory record" } = {}) {
  if (!record?.id) throw new Error(`${label} is no longer loaded. Reload before saving.`);
  return replaceEntityFieldsIfUnchanged({
    entity,
    id: record.id,
    expectedUpdatedAt: record.updated_date || "",
    expectedFields: expectedEntityFields(record, nextFields),
    nextFields,
    guardFields: { vinyl_name: record.vinyl_name },
    label,
  });
}

export async function deleteVinylIfUnchanged({ entity, record, label = "Vinyl inventory record" } = {}) {
  if (!record?.id) throw new Error(`${label} is no longer loaded. Reload before deleting.`);
  return deleteEntityIfUnchanged({
    entity,
    record,
    guardFields: { vinyl_name: record.vinyl_name },
    label,
  });
}

export async function duplicateVinylSafely({
  entity,
  source,
  copyData,
  groupKey,
  label = "Vinyl inventory duplicate",
} = {}) {
  if (!source?.id) throw new Error(`${label} source is no longer loaded.`);
  if (typeof entity?.get !== "function") throw new Error(`${label} could not verify its source record.`);

  const live = await entity.get(source.id);
  if (!live?.id || String(live.updated_date || "") !== String(source.updated_date || "")) {
    throw new Error(`${label} was blocked because the source vinyl changed in another session.`);
  }

  const copyResult = await createVinylRecordWithRecovery({ entity, data: copyData, label });
  let savedSource = live;

  if (!live.product_group_key) {
    try {
      savedSource = await updateVinylIfUnchanged({
        entity,
        record: live,
        nextFields: { product_group_key: groupKey },
        label: `${label} source grouping`,
      });
    } catch (error) {
      if (copyResult.ownershipCertain) {
        try {
          await deleteVinylIfUnchanged({
            entity,
            record: copyResult.record,
            label: `${label} rollback copy`,
          });
        } catch (rollbackError) {
          throw new Error(`${error?.message || `${label} could not group the source.`} The new copy also could not be rolled back safely: ${rollbackError?.message || "rollback failed"}`);
        }
      } else {
        throw new Error(`${error?.message || `${label} could not group the source.`} The create response was ambiguous, so no uncertain copy was deleted; reload and review the matching vinyl records.`);
      }
      throw error;
    }
  }

  return { source: savedSource, copy: copyResult.record, copyStatus: copyResult.status };
}

export { stripMeta as stripVinylRecordMeta };

// The full Vinyl Inventory tab. Used in three places:
//   - Master Inventory (scope="master")        → shows everything
//   - Channel & Dimensional Letters Inventory  → scope="channel_letters"
//   - Sign Maintenance Inventory               → scope="sign_maintenance"
//   - Dedicated Vinyl Inventory page (under Vinyl Estimator)
//
// Editing flow:
//   - "Add Vinyl"  → creates a blank record, immediately opens VinylEditDialog.
//   - Row "Edit"   → opens VinylEditDialog populated with that row.
//   - Save in dialog persists the full draft through guarded VinylInventory persistence.

import { useEffect, useState, useMemo, useRef } from "react";
import { VinylInventory, User } from "@/api/gatedEntities";
import { loadAllEntityRows } from "@/components/estimator/loadAllEntityRows";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Plus, Search, Droplets, Lock } from "lucide-react";
import VinylRowCard from "./VinylRowCard";
import VinylEditDialog from "./VinylEditDialog";
import { VINYL_CATEGORIES, VINYL_USE_CASES, filterVinylForScope } from "./vinylConstants";
import { createVinylRecordWithRecovery, deleteVinylIfUnchanged, duplicateVinylSafely, stripVinylRecordMeta, updateVinylIfUnchanged } from "./vinylInventoryPersistence";

const SCOPE_META = {
  master:           { label: "All Vinyl", color: "text-blue-600",    accent: "bg-blue-50 border-blue-200" },
  channel_letters:  { label: "Channel & Dimensional Letters", color: "text-purple-600", accent: "bg-purple-50 border-purple-200" },
  sign_maintenance: { label: "Sign Maintenance",  color: "text-cyan-600", accent: "bg-cyan-50 border-cyan-200" },
};

const blankVinyl = (scope) => ({
  vinyl_name: "New Vinyl",
  vinyl_category: "calendered",
  vinyl_use_case: "cut_graphics",
  finish: "gloss",
  roll_width_inches: 24,
  roll_length_yards: 50,
  thickness_mil: 2,
  pricing_mode: "per_roll",
  cost_per_roll: 0,
  waste_factor_percent: 15,
  yield_factor: 0.85,
  adhesive_type: "permanent",
  application_method: "either",
  indoor_outdoor: "both",
  weeding_difficulty: "moderate",
  is_active: true,
  show_in_channel_letters: scope !== "sign_maintenance",
  show_in_sign_maintenance: scope !== "channel_letters",
  show_in_vinyl_estimator: true,
});

export default function VinylInventoryTab({ scope = "master" }) {
  const meta = SCOPE_META[scope] || SCOPE_META.master;
  const [items, setItems] = useState([]);
  const [loading, setLoading] = useState(true);
  const [user, setUser] = useState(null);
  const [search, setSearch] = useState(() => {
    try { return new URLSearchParams(window.location.search).get("q") || ""; } catch { return ""; }
  });
  const [categoryFilter, setCategoryFilter] = useState(() => {
    try { return new URLSearchParams(window.location.search).get("category") || "all"; } catch { return "all"; }
  });
  const [useCaseFilter, setUseCaseFilter] = useState(() => {
    try { return new URLSearchParams(window.location.search).get("use_case") || "all"; } catch { return "all"; }
  });
  const writeParam = (key, value, defaultValue = "all") => {
    try {
      const next = new URLSearchParams(window.location.search);
      if (value && value !== defaultValue) next.set(key, value); else next.delete(key);
      window.history.replaceState(null, "", `${window.location.pathname}?${next}`);
    } catch {}
  };
  const [editingVinyl, setEditingVinyl] = useState(null);
  const [loadError, setLoadError] = useState("");
  const [persistenceError, setPersistenceError] = useState("");
  const itemActionRef = useRef(new Set());
  const addRef = useRef(false);
  const isAdmin = user?.role === "admin";

  const load = async () => {
    setLoading(true);
    setLoadError("");
    try {
      const all = await loadAllEntityRows({ entity: VinylInventory, sort: "sort_order", label: "Vinyl inventory" });
      setItems(all);
    } catch (e) {
      console.error("Failed to load VinylInventory:", e);
      setLoadError(e?.message || "Vinyl inventory could not be verified.");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    User.me().then(setUser).catch(() => setUser(null));
    load();
  }, []);

  const filtered = useMemo(() => {
    let list = filterVinylForScope(items, scope);
    if (categoryFilter !== "all") list = list.filter(v => v.vinyl_category === categoryFilter);
    if (useCaseFilter !== "all")  list = list.filter(v => v.vinyl_use_case === useCaseFilter);
    if (search.trim()) {
      const q = search.toLowerCase();
      list = list.filter(v =>
        [v.vinyl_name, v.manufacturer, v.product_series, v.color_name, v.supplier, v.supplier_sku, v.notes]
          .filter(Boolean).some(s => String(s).toLowerCase().includes(q))
      );
    }
    return list;
  }, [items, scope, search, categoryFilter, useCaseFilter]);

  const handleAdd = async () => {
    if (!isAdmin || loadError || addRef.current) return;
    addRef.current = true;
    setPersistenceError("");
    try {
      const result = await createVinylRecordWithRecovery({
        entity: VinylInventory,
        data: { ...blankVinyl(scope), sort_order: items.length + 1 },
        label: "New vinyl inventory record",
      });
      setItems(prev => [result.record, ...prev.filter((row) => row.id !== result.record.id)]);
      setEditingVinyl(result.record);
    } catch (e) {
      console.error(e);
      setPersistenceError(e?.message || "The new vinyl record could not be created safely.");
    } finally {
      addRef.current = false;
    }
  };

  const handleDialogSave = async (draft) => {
    if (!draft?.id || itemActionRef.current.has(draft.id)) return;
    itemActionRef.current.add(draft.id);
    setPersistenceError("");
    try {
      const baseline = items.find((row) => row.id === draft.id);
      if (!baseline) throw new Error("This vinyl is no longer in the loaded inventory. Reload before saving.");
      const patch = stripVinylRecordMeta(draft);
      const saved = await updateVinylIfUnchanged({
        entity: VinylInventory,
        record: baseline,
        nextFields: patch,
        label: `Vinyl ${baseline.vinyl_name || baseline.id}`,
      });
      setItems(prev => prev.map(v => v.id === saved.id ? saved : v));
      setEditingVinyl(null);
    } catch (e) {
      console.error(e);
      const live = await VinylInventory.get(draft.id).catch(() => null);
      if (live?.id) {
        setItems(prev => prev.map(v => v.id === draft.id ? live : v));
        setEditingVinyl(live);
      }
      setPersistenceError(e?.message || "This vinyl changed in another session. The latest record was reloaded and your stale save was blocked.");
    } finally {
      itemActionRef.current.delete(draft.id);
    }
  };

  const handleDelete = async (vinyl) => {
    if (!isAdmin || !vinyl?.id || itemActionRef.current.has(vinyl.id)) return;
    itemActionRef.current.add(vinyl.id);
    if (!confirm("Delete this vinyl?")) {
      itemActionRef.current.delete(vinyl.id);
      return;
    }
    setPersistenceError("");
    try {
      await deleteVinylIfUnchanged({
        entity: VinylInventory,
        record: vinyl,
        label: `Vinyl ${vinyl.vinyl_name || vinyl.id} deletion`,
      });
      setItems(prev => prev.filter(v => v.id !== vinyl.id));
    } catch (e) {
      console.error(e);
      const live = await VinylInventory.get(vinyl.id).catch(() => null);
      if (live?.id) setItems(prev => prev.map(v => v.id === vinyl.id ? live : v));
      setPersistenceError(e?.message || "This vinyl changed in another session and was not deleted.");
    } finally {
      itemActionRef.current.delete(vinyl.id);
    }
  };

  // #13 Quick-duplicate. Auto-links rows into a product group so the roll-width
  // recommender can find them. If the source has no product_group_key, we
  // generate one and stamp it on both rows.
  const handleDuplicate = async (source) => {
    if (!isAdmin || !source?.id || itemActionRef.current.has(source.id)) return;
    itemActionRef.current.add(source.id);
    setPersistenceError("");
    try {
      const groupKey = source.product_group_key || `grp-${source.id}`;
      const copy = {
        ...stripVinylRecordMeta(source),
        product_group_key: groupKey,
        vinyl_name: `${source.vinyl_name || "Vinyl"} (copy)`,
        sort_order: (source.sort_order || 0) + 0.1,
      };
      const result = await duplicateVinylSafely({
        entity: VinylInventory,
        source,
        copyData: copy,
        groupKey,
        label: `Duplicate vinyl ${source.vinyl_name || source.id}`,
      });
      setItems(prev => [
        result.copy,
        ...prev.filter(v => v.id !== result.copy.id).map(v => v.id === result.source.id ? result.source : v),
      ]);
      setEditingVinyl(result.copy);
    } catch (e) {
      console.error(e);
      const live = await VinylInventory.get(source.id).catch(() => null);
      if (live?.id) setItems(prev => prev.map(v => v.id === source.id ? live : v));
      setPersistenceError(e?.message || "This vinyl could not be duplicated safely. Reload before retrying.");
    } finally {
      itemActionRef.current.delete(source.id);
    }
  };

  return (
    <Card className="bg-white border-0 shadow-sm">
      <CardHeader className="pb-3">
        <div className="flex flex-col lg:flex-row lg:items-center lg:justify-between gap-3">
          <CardTitle className="flex items-center gap-2 text-lg">
            <Droplets className={`w-5 h-5 ${meta.color}`} />
            Vinyl Inventory
            <Badge variant="outline" className={`ml-1 text-[10px] ${meta.accent}`}>{meta.label}</Badge>
            <Badge variant="outline" className="ml-1 font-normal">{filtered.length} of {items.length}</Badge>
          </CardTitle>

          <div className="flex flex-col sm:flex-row gap-2 w-full lg:w-auto">
            <div className="relative w-full sm:w-64">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
              <Input
                placeholder="Search vinyl…"
                value={search}
                onChange={(e) => { const v = e.target.value; setSearch(v); writeParam("q", v, ""); }}
                className="pl-9 h-9 text-sm"
              />
            </div>
            <Select value={categoryFilter} onValueChange={(v) => { setCategoryFilter(v); writeParam("category", v); }}>
              <SelectTrigger className="h-9 text-sm w-40"><SelectValue placeholder="Category" /></SelectTrigger>
              <SelectContent>
                <SelectItem value="all">All Categories</SelectItem>
                {VINYL_CATEGORIES.map(c => <SelectItem key={c.id} value={c.id}>{c.label}</SelectItem>)}
              </SelectContent>
            </Select>
